import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SearchBarTypingProps = Record<string, any>;

const SearchBarTyping: React.FC<SearchBarTypingProps> = ({
  backgroundColor = "#f5f5f5",
  transparentBackground = true,
  durationInSeconds = 10,
  searchQueries = [
    "why use spf daily",
    "benefits of sunscreen",
    "best skincare routine"
  ],
  finalQuery = "YSE Skin Glow?",
  borderColor = "#111111",
  textColor = "#111111",
  cursorColor = "#111111",
  barFillColor = "#ffffff",
}) => {
  useFontLoader([]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing
  const minDim = Math.min(width, height);
  const barWidth = width * 0.65;
  const barHeight = minDim * 0.12;
  const fontSize = minDim * 0.045;
  const iconSize = minDim * 0.05;

  // Initial Entry Animation for the Search Bar
  const barScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.6, stiffness: 100 },
  });

  // Calculate Typing Dynamics
  const totalFrames = fps * durationInSeconds;
  const finalHoldFrames = fps * 2.5; // Final text holds for 2.5 seconds
  const availableLoopFrames = Math.max(1, totalFrames - finalHoldFrames);
  
  const timePerQuery = Math.floor(availableLoopFrames / Math.max(1, searchQueries.length));

  let currentString = "";
  let accumulatedFrames = 0;
  let activeIndex = -1;

  for (let i = 0; i < searchQueries.length; i++) {
    const query = searchQueries[i];
    const startFrame = accumulatedFrames;
    const endFrame = startFrame + timePerQuery;

    if (frame >= startFrame && frame < endFrame) {
      activeIndex = i;
      const localFrame = frame - startFrame;
      
      // Dynamic allocation: 40% typing, 35% hold, 25% deleting
      const typeFrames = Math.floor(timePerQuery * 0.4);
      const holdFrames = Math.floor(timePerQuery * 0.35);
      const delFrames = timePerQuery - typeFrames - holdFrames;

      if (localFrame < typeFrames) {
        // Typing Phase
        const progress = localFrame / typeFrames;
        const chars = Math.floor(query.length * progress);
        currentString = query.substring(0, chars);
      } else if (localFrame < typeFrames + holdFrames) {
        // Holding Phase
        currentString = query;
      } else {
        // Deleting Phase
        const progress = (localFrame - typeFrames - holdFrames) / Math.max(1, delFrames);
        const chars = Math.max(0, query.length - Math.floor(query.length * progress));
        currentString = query.substring(0, chars);
      }
      break;
    }
    accumulatedFrames += timePerQuery;
  }

  // Handle the final query if all previous queries are done
  if (activeIndex === -1 && frame >= accumulatedFrames) {
    const finalTypeDuration = fps * 1.5; // 1.5 seconds to type the final query
    const localFrame = frame - accumulatedFrames;
    const progress = Math.min(1, Math.max(0, localFrame / finalTypeDuration));
    const chars = Math.floor(finalQuery.length * progress);
    currentString = finalQuery.substring(0, chars);
  }

  // Cursor blink logic
  const cursorBlinkRate = 15; // frames per blink
  const showCursor = Math.floor(frame / cursorBlinkRate) % 2 === 0;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Helvetica, Arial, sans-serif",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          width: barWidth,
          height: barHeight,
          backgroundColor: barFillColor,
          border: `4px solid ${borderColor}`,
          borderRadius: barHeight / 2,
          padding: `0 ${barHeight * 0.4}px`,
          transform: `scale(${barScale})`,
          boxShadow: `0 24px 48px rgba(0,0,0,0.05)`,
          transition: "none",
        }}
      >
        {/* Search Icon */}
        <svg
          width={iconSize}
          height={iconSize}
          viewBox="0 0 24 24"
          fill="none"
          stroke={borderColor}
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ marginRight: barHeight * 0.3, flexShrink: 0 }}
        >
          <circle cx="11" cy="11" r="8"></circle>
          <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
        </svg>

        {/* Text Container */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            flex: 1,
            height: "100%",
            overflow: "hidden",
            whiteSpace: "pre",
          }}
        >
          <span
            style={{
              fontSize: fontSize,
              fontWeight: 500,
              color: textColor,
              lineHeight: 1,
              transition: "none",
            }}
          >
            {currentString}
          </span>
          {/* Blinking Cursor */}
          <div
            style={{
              width: fontSize * 0.08,
              height: fontSize * 1.1,
              backgroundColor: cursorColor,
              marginLeft: fontSize * 0.1,
              opacity: showCursor ? 1 : 0,
              transition: "none",
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SearchBarTyping;